CREATE TABLE IF NOT EXISTS devices(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),user_id uuid REFERENCES users(id) ON DELETE CASCADE,device_key text NOT NULL,platform text,app_version text,last_seen_at timestamptz NOT NULL DEFAULT now(),UNIQUE(user_id,device_key));
CREATE TABLE IF NOT EXISTS refresh_tokens(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),user_id uuid REFERENCES users(id) ON DELETE CASCADE,token_hash text UNIQUE NOT NULL,expires_at timestamptz NOT NULL,revoked_at timestamptz,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS artist_profiles(artist_id uuid PRIMARY KEY REFERENCES artists(id) ON DELETE CASCADE,avatar_url text,header_url text,links jsonb NOT NULL DEFAULT '{}'::jsonb,genres text[] NOT NULL DEFAULT '{}',country_code char(2),updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS releases(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),artist_id uuid REFERENCES artists(id) ON DELETE CASCADE,title text NOT NULL,upc text UNIQUE,kind text NOT NULL,release_date date,status text NOT NULL DEFAULT 'draft',artwork_key text,notes text,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS release_tracks(release_id uuid REFERENCES releases(id) ON DELETE CASCADE,track_id uuid REFERENCES tracks(id) ON DELETE CASCADE,disc_no int NOT NULL DEFAULT 1,track_no int NOT NULL,PRIMARY KEY(release_id,track_id));
CREATE TABLE IF NOT EXISTS credits(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),track_id uuid REFERENCES tracks(id) ON DELETE CASCADE,name text NOT NULL,role text NOT NULL,ipi text,pro text);CREATE INDEX IF NOT EXISTS credits_track_idx ON credits(track_id);
CREATE TABLE IF NOT EXISTS rights_history(id bigserial PRIMARY KEY,rights_id uuid,track_id uuid REFERENCES tracks(id) ON DELETE CASCADE,territory char(2) NOT NULL,action text NOT NULL,payload jsonb NOT NULL DEFAULT '{}',created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS takedown_requests(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),track_id uuid REFERENCES tracks(id) ON DELETE CASCADE,reporter text,reason text NOT NULL,status text NOT NULL DEFAULT 'open',created_at timestamptz NOT NULL DEFAULT now(),resolved_at timestamptz);
CREATE TABLE IF NOT EXISTS notification_preferences(user_id uuid PRIMARY KEY REFERENCES users(id) ON DELETE CASCADE,email boolean NOT NULL DEFAULT true,push boolean NOT NULL DEFAULT true,new_releases boolean NOT NULL DEFAULT true,recommendations boolean NOT NULL DEFAULT true);
CREATE TABLE IF NOT EXISTS listening_sessions(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),user_id uuid REFERENCES users(id) ON DELETE SET NULL,device_id text,country_code char(2),started_at timestamptz NOT NULL DEFAULT now(),ended_at timestamptz);
CREATE TABLE IF NOT EXISTS catalog_ingest_jobs(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),provider text NOT NULL,status text NOT NULL DEFAULT 'queued',source_ref text,records_total int DEFAULT 0,records_ok int DEFAULT 0,records_failed int DEFAULT 0,error_log jsonb NOT NULL DEFAULT '[]',created_at timestamptz NOT NULL DEFAULT now(),completed_at timestamptz);
CREATE INDEX IF NOT EXISTS tracks_artist_idx ON tracks(artist_id);CREATE INDEX IF NOT EXISTS tracks_album_idx ON tracks(album_id);CREATE INDEX IF NOT EXISTS rights_track_territory_idx ON rights(track_id,territory);CREATE INDEX IF NOT EXISTS events_track_time_idx ON listening_events(track_id,occurred_at DESC);